static char* parse_string_token(const char* s) {
    const char* p = s;
    while (*p && *p != '"') p++;
    if (!*p) return NULL;
    p++;
    const char* start = p;
    while (*p && *p != '"') p++;
    size_t len = p - start;
    char* out = malloc(len + 1);
    strncpy(out, start, len);
    out[len] = '\0';
